"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["41348"],{83055(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.quorum_incoerente","status":422,"titulo":"Com o encerramento por todos os titulares, o qu\xf3rum \xe9 o n\xfamero de integrantes"},"descricao":{"codigo":"uniplus.selecao.banca.quorum_incoerente","requisitos":["UNI-REQ-0275","UNI-REQ-0399"],"oQueAconteceu":["A banca declara que a vota\xe7\xe3o termina quando todos os titulares votam\\n(`TODOS_OS_TITULARES`), mas o qu\xf3rum \xe9 diferente do n\xfamero de integrantes. As duas\\ndeclara\xe7\xf5es se contradizem: se todos precisam votar, o qu\xf3rum \xe9 o n\xfamero de\\nintegrantes. Com 3 integrantes, encerramento por todos os titulares e qu\xf3rum 2,\\na regra diz duas coisas diferentes sobre quando a vota\xe7\xe3o acaba.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.quorum` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.quorum` na banca da etapa."],"comoResolver":["Escolha o que o edital quer dizer:","- **A vota\xe7\xe3o termina com todos os titulares.** Use o pr\xf3prio n\xfamero de\\n  integrantes como qu\xf3rum.\\n- **A vota\xe7\xe3o termina quando o qu\xf3rum \xe9 atingido.** Declare o encerramento\\n  `PRESIDENCIA_NO_QUORUM`: a presid\xeancia encerra ao atingir o qu\xf3rum, e o qu\xf3rum\\n  pode ser menor que o n\xfamero de integrantes.","Um qu\xf3rum de zero ou acima do n\xfamero de integrantes tem\\n[recusa pr\xf3pria](/erros/uniplus.selecao.banca.quorum_fora_do_intervalo)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);